<?php
$adminPageTitle="Competências da Assembleia";
$adminActive="assembleia_competencias";
require_once "includes/header.php";
requireAssembleiaManager();
$erro='';$sucesso='';$tipos=['fiscalizacao','deliberativa','comunidade','transparencia','timeline','destaque'];
function getConfigCompetencias($pdo){$stmt=$pdo->query("SELECT * FROM assembleia_competencias_config ORDER BY id ASC LIMIT 1");$c=$stmt->fetch(PDO::FETCH_ASSOC);if(!$c){$pdo->query("INSERT INTO assembleia_competencias_config (hero_titulo,hero_subtitulo,intro_titulo,intro_texto) VALUES ('Atribuições e Competências','Conheça as competências da Assembleia de Freguesia.','Órgão deliberativo da freguesia','Texto introdutório.')");$c=$pdo->query("SELECT * FROM assembleia_competencias_config ORDER BY id ASC LIMIT 1")->fetch(PDO::FETCH_ASSOC);}return $c;}
if($_SERVER['REQUEST_METHOD']==='POST'){$acao=$_POST['acao']??'';if($acao==='config'){$id=(int)($_POST['id']??0);$vals=[trim($_POST['hero_kicker']??''),trim($_POST['hero_titulo']??''),trim($_POST['hero_subtitulo']??''),trim($_POST['intro_titulo']??''),trim($_POST['intro_texto']??''),trim($_POST['destaque_1_titulo']??''),trim($_POST['destaque_1_valor']??''),trim($_POST['destaque_2_titulo']??''),trim($_POST['destaque_2_valor']??''),trim($_POST['destaque_3_titulo']??''),trim($_POST['destaque_3_valor']??''),$id];if(!$vals[1])$erro="O título principal é obrigatório.";else{$stmt=$pdo->prepare("UPDATE assembleia_competencias_config SET hero_kicker=?,hero_titulo=?,hero_subtitulo=?,intro_titulo=?,intro_texto=?,destaque_1_titulo=?,destaque_1_valor=?,destaque_2_titulo=?,destaque_2_valor=?,destaque_3_titulo=?,destaque_3_valor=?,atualizado_em=NOW() WHERE id=?");$stmt->execute($vals);$sucesso="Conteúdo principal atualizado.";}}if($acao==='bloco'){$id=(int)($_POST['id']??0);$titulo=trim($_POST['titulo']??'');$subtitulo=trim($_POST['subtitulo']??'');$conteudo=trim($_POST['conteudo']??'');$lista=trim($_POST['lista']??'');$icone=trim($_POST['icone']??'');$tipo=trim($_POST['tipo']??'fiscalizacao');$ordem=(int)($_POST['ordem']??0);$ativo=isset($_POST['ativo'])?1:0;if(!$titulo||!in_array($tipo,$tipos))$erro="Preencha o título e escolha um tipo válido.";else{if($id>0){$stmt=$pdo->prepare("UPDATE assembleia_competencias_blocos SET titulo=?,subtitulo=?,conteudo=?,lista=?,icone=?,tipo=?,ordem=?,ativo=?,atualizado_em=NOW() WHERE id=?");$stmt->execute([$titulo,$subtitulo,$conteudo,$lista,$icone,$tipo,$ordem,$ativo,$id]);$sucesso="Bloco atualizado.";}else{$stmt=$pdo->prepare("INSERT INTO assembleia_competencias_blocos (titulo,subtitulo,conteudo,lista,icone,tipo,ordem,ativo) VALUES (?,?,?,?,?,?,?,?)");$stmt->execute([$titulo,$subtitulo,$conteudo,$lista,$icone,$tipo,$ordem,$ativo]);$sucesso="Bloco criado.";}}}}
if(isset($_GET['apagar'])){$pdo->prepare("DELETE FROM assembleia_competencias_blocos WHERE id=?")->execute([(int)$_GET['apagar']]);header("Location: assembleia-competencias.php");exit;}
if(isset($_GET['toggle'])){$pdo->prepare("UPDATE assembleia_competencias_blocos SET ativo=IF(ativo=1,0,1), atualizado_em=NOW() WHERE id=?")->execute([(int)$_GET['toggle']]);header("Location: assembleia-competencias.php");exit;}
$config=getConfigCompetencias($pdo);$editarBloco=null;if(isset($_GET['editar'])){$stmt=$pdo->prepare("SELECT * FROM assembleia_competencias_blocos WHERE id=?");$stmt->execute([(int)$_GET['editar']]);$editarBloco=$stmt->fetch(PDO::FETCH_ASSOC);}$blocos=$pdo->query("SELECT * FROM assembleia_competencias_blocos ORDER BY ordem ASC,id ASC")->fetchAll(PDO::FETCH_ASSOC);$total=count($blocos);$ativos=0;$deliberativas=0;$fiscalizacao=0;foreach($blocos as $b){if($b['ativo'])$ativos++;if($b['tipo']==='deliberativa')$deliberativas++;if($b['tipo']==='fiscalizacao')$fiscalizacao++;}
?>
