ding:14px;display:grid;grid-template-columns:54px 1fr auto;gap:14px;align-items:center;margin-bottom:12px}.bloco-icon{width:54px;height:54px;border-radius:16px;background:#242A30;color:white;display:grid;place-items:center;font-size:24px}.bloco-row h4{margin:0 0 5px;color:#11151B}.bloco-row p{margin:0;color:#64748b;font-weight:800;font-size:13px}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef2ff;color:#242A30;font-size:11px;font-weight:900;margin-right:5px}.badge.off{background:#fee2e2;color:#991b1b}@media(max-width:1100px){.compadmin-grid,.compadmin-hero{grid-template-columns:1fr}.compadmin-kpis{grid-template-columns:1fr 1fr}.bloco-row{grid-template-columns:1fr}}@media(max-width:700px){.compadmin-kpis,.comp-form-grid{grid-template-columns:1fr}}</style>
