h4><p><span class="badge"><?= htmlspecialchars($b['tipo']) ?></span><span class="badge">Ordem <?= (int)$b['ordem'] ?></span><?php if(!$b['ativo']):?><span class="badge off">Inativo</span><?php endif;?></p></div><div class="comp-actions"><a class="btn secondary" href="assembleia-competencias.php?editar=<?= (int)$b['id'] ?>">Editar</a><a class="btn secondary" href="assembleia-competencias.php?toggle=<?= (int)$b['id'] ?>"><?= $b['ativo']?'Ocultar':'Mostrar' ?></a><a class="btn danger" href="assembleia-competencias.php?apagar=<?= (int)$b['id'] ?>" onclick="return confirm('Apagar este bloco?')">Apagar</a></div></div><?php endforeach;?><?php if(empty($blocos)):?><p>Ainda não existem blocos.</p><?php endif;?></div></div>
